package io.github.rottencandy.openwizlight.wiz

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Expected values were generated by running pywizlight's `hs2rgbcw` and `rgbcw2hs` on the same
 * inputs. The conversion isn't an exact inverse, so the reverse cases don't round-trip.
 */
class RgbCwTest {

    @Test
    fun `hsToRgbCw matches pywizlight`() {
        val cases = listOf(
            HueSat(0, 100) to RgbCw(255, 0, 0, 0),
            HueSat(100, 50) to RgbCw(88, 255, 0, 128), // also pywizlight's test_PilotBuilder_hucolor
            HueSat(60, 100) to RgbCw(255, 254, 0, 0),
            HueSat(210, 65) to RgbCw(0, 127, 255, 89),
            HueSat(300, 25) to RgbCw(127, 0, 127, 128),
            HueSat(0, 0) to RgbCw(0, 0, 0, 128),
            HueSat(120, 75) to RgbCw(0, 255, 0, 64),
            HueSat(359, 90) to RgbCw(255, 0, 5, 25),
            HueSat(240, 100) to RgbCw(0, 0, 255, 0),
            HueSat(30, 50) to RgbCw(255, 127, 0, 128),
        )
        cases.forEach { (hs, expected) -> assertEquals("$hs", expected, hsToRgbCw(hs)) }
    }

    @Test
    fun `rgbCwToHs matches pywizlight, rounded`() {
        val cases = listOf(
            RgbCw(255, 0, 0, 0) to HueSat(0, 100),
            RgbCw(88, 255, 0, 128) to HueSat(100, 44), // pywizlight: 100.141, 43.988
            RgbCw(255, 254, 0, 0) to HueSat(60, 100), // 59.805
            RgbCw(0, 127, 255, 89) to HueSat(210, 65), // 210.130, 65.234
            RgbCw(127, 0, 127, 128) to HueSat(300, 25), // 24.902
            RgbCw(0, 0, 0, 128) to HueSat(0, 0),
            RgbCw(0, 255, 0, 64) to HueSat(120, 75),
            RgbCw(255, 0, 5, 25) to HueSat(359, 90), // 359.018, 90.234
            RgbCw(0, 0, 255, 0) to HueSat(240, 100),
            RgbCw(255, 127, 0, 128) to HueSat(30, 43), // 29.870, 43.301
        )
        cases.forEach { (rgbCw, expected) ->
            assertEquals("$rgbCw", expected, rgbCwToHs(rgbCw.r, rgbCw.g, rgbCw.b, rgbCw.w))
        }
    }

    @Test
    fun `white above the maximum the app sends is treated as full white`() {
        assertEquals(rgbCwToHs(127, 0, 127, 128), rgbCwToHs(127, 0, 127, 255))
    }

    @Test
    fun `hue 360 wraps to 0`() {
        assertEquals(hsToRgbCw(HueSat(0, 80)), hsToRgbCw(HueSat(360, 80)))
    }
}
